<?php
namespace KaarBooking\Component\KaarBooking\Administrator\Controller;defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use KaarBooking\Component\KaarBooking\Administrator\Service\MediaUploadService;
final class PackagesController extends BaseController{public function save():void{Session::checkToken('post')or jexit('Invalid token');if(!$this->app->getIdentity()->authorise('core.create','com_kaarbooking'))throw new \RuntimeException('Not authorised',403);$title=trim($this->input->post->getString('title'));if($title==='')throw new \DomainException('Package title is required.');$alias=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$title),'-')).'-'.substr(bin2hex(random_bytes(3)),0,6);$db=Factory::getContainer()->get(\Joomla\Database\DatabaseInterface::class);$now=Factory::getDate()->toSql();$row=(object)['title'=>mb_substr($title,0,190),'alias'=>$alias,'summary'=>trim($this->input->post->getString('summary')),'description'=>trim($this->input->post->getString('description')),'duration_days'=>max(1,$this->input->post->getInt('duration_days')),'duration_nights'=>max(0,$this->input->post->getInt('duration_nights')),'booking_mode'=>$this->input->post->getCmd('booking_mode','whole_vehicle'),'vehicle_type_id'=>$this->input->post->getInt('vehicle_type_id')?:null,'capacity'=>$this->input->post->getInt('capacity')?:null,'base_price'=>max(0,$this->input->post->getFloat('base_price')),'currency'=>strtoupper(mb_substr($this->input->post->getCmd('currency','INR'),0,3)),'sale_start'=>null,'sale_end'=>null,'state'=>$this->input->post->getInt('state')?1:0,'ordering'=>0,'created'=>$now,'modified'=>null];$db->insertObject('#__kaar_packages',$row,'id');MediaUploadService::store($this->input->files->get('package_images',[],'array'),'package',(int)$row->id,(int)$this->app->getIdentity()->id,2,4,'gallery');foreach(preg_split('/\R/',trim($this->input->post->getString('inclusions')))?:[] as $i=>$line){$line=trim($line);if($line!=='')$db->insertObject('#__kaar_package_items',(object)['package_id'=>$row->id,'item_type'=>'included','title'=>mb_substr($line,0,255),'description'=>null,'ordering'=>$i,'state'=>1]);}$this->app->enqueueMessage('Package added.','success');$this->setRedirect(Route::_('index.php?option=com_kaarbooking&view=packages',false));}}


